const previousConnectionQrLogin=connectionView;
connectionView=function(){previousConnectionQrLogin();$('#view').insertAdjacentHTML('beforeend','<div class="panel" style="margin-top:20px"><h3>Dashboard QR sign-in</h3><p>Register the connected WhatsApp number for future Client login QR scans. Your dashboard password is required to enable or remove this login method.</p><div id="qr-login-binding">Loading...</div></div>');loadQrBinding()};
async function loadQrBinding(){try{const {binding}=await api('/auth/qr/binding');if(!$('#qr-login-binding'))return;$('#qr-login-binding').innerHTML=`<p>${binding?'Registered number: '+esc(binding.phone):'QR sign-in is not enabled for this store.'}</p><button class="btn secondary" id="bind-qr-login">${binding?'Update registered number':'Enable QR sign-in'}</button> ${binding?'<button class="btn secondary" id="unbind-qr-login">Remove QR sign-in</button>':''}<p><a href="/client-login">Open Client QR login</a></p>`;$('#bind-qr-login').onclick=()=>qrBindingForm(false);if(binding)$('#unbind-qr-login').onclick=()=>qrBindingForm(true)}catch(e){if($('#qr-login-binding'))$('#qr-login-binding').textContent=e.message}}
function qrBindingForm(remove){modal(`<h2>${remove?'Remove':'Enable'} QR sign-in</h2><p>${remove?'Future QR scans will no longer sign in to this store.':'Your currently connected WhatsApp number will become a dashboard sign-in method. Only register a number controlled by the store owner.'}</p><form id="edit-form">${input('password','Current dashboard password','','password','required autocomplete="current-password" maxlength="200"')}${formEnd(remove?'Remove QR sign-in':'Enable QR sign-in')}`);bindForm(async b=>{await api('/auth/qr/binding',remove?'DELETE':'POST',{password:b.password});await loadQrBinding();toast('QR login settings saved')})}
